import { z } from 'zod'
import { CAPTION_MAX_LENGTH } from '@/lib/whatsapp/attachments'
import { REPLY_TEXT_MAX_LENGTH } from '@/lib/whatsapp/composer'
import { CLOSE_REASON_MAX_LENGTH } from '@/lib/whatsapp/handoff'
import { SEARCH_MAX_LENGTH } from '@/lib/whatsapp/search'
import { TEMPLATE_KEYS } from '@/lib/whatsapp/templates'

/** Message ids are cuids generated by Prisma; anything else is rejected before touching the DB. */
export const getMediaUrlSchema = z.object({
  messageId: z.string({ required_error: 'El mensaje es requerido' }).cuid('Mensaje inválido'),
})

export type GetMediaUrlInput = z.infer<typeof getMediaUrlSchema>

export const INBOX_PAGE_SIZE_DEFAULT = 50
export const INBOX_PAGE_SIZE_MAX = 100

const conversationId = z
  .string({ required_error: 'La conversación es requerida' })
  .cuid('Conversación inválida')

export const listConversationsSchema = z.object({
  state: z.enum(['AI', 'HUMAN', 'ESCALATED', 'CLOSED'], { invalid_type_error: 'Estado inválido' }).optional(),
  limit: z
    .number({ invalid_type_error: 'Límite inválido' })
    .int('Límite inválido')
    .min(1, 'Límite inválido')
    .max(INBOX_PAGE_SIZE_MAX, 'Límite inválido')
    .default(INBOX_PAGE_SIZE_DEFAULT),
  cursor: z.string().cuid('Cursor inválido').optional(),
  /** Search box text: contact name or phone digits. Blank means no search. */
  q: z
    .string({ invalid_type_error: 'Búsqueda inválida' })
    .max(SEARCH_MAX_LENGTH, 'La búsqueda es demasiado larga')
    .optional(),
})

export const threadCursor = z.object({
  timestamp: z.string({ required_error: 'Cursor inválido' }).datetime({ message: 'Cursor inválido' }),
  id: z.string({ required_error: 'Cursor inválido' }).cuid('Cursor inválido'),
})

export const getConversationThreadSchema = z.object({
  conversationId,
  /**
   * History cursor: the oldest message already loaded. It is composite (timestamp, id) because
   * several messages can share one timestamp (second-resolution webhooks, bursts), and a
   * timestamp-only cursor would skip the ones left on the other side of a page boundary.
   */
  before: threadCursor.optional(),
  limit: z
    .number({ invalid_type_error: 'Límite inválido' })
    .int('Límite inválido')
    .min(1, 'Límite inválido')
    .max(INBOX_PAGE_SIZE_MAX, 'Límite inválido')
    .default(INBOX_PAGE_SIZE_DEFAULT),
})

export const getUpdatesSchema = z.object({
  /** ISO timestamp returned by the previous list, thread or updates call. */
  updatedSince: z.string({ required_error: 'El cursor es requerido' }).datetime({ message: 'Cursor inválido' }),
  conversationId: conversationId.optional(),
})

export const markConversationReadInboxSchema = z.object({ conversationId })

export type ListConversationsInput = z.input<typeof listConversationsSchema>
// ---------------------------------------------------------------- sending (PR2.3)

export const sendReplySchema = z.object({
  conversationId,
  text: z
    .string({ required_error: 'El mensaje es requerido' })
    .trim()
    .min(1, 'El mensaje es requerido')
    .max(REPLY_TEXT_MAX_LENGTH, `El mensaje no puede superar ${REPLY_TEXT_MAX_LENGTH} caracteres`),
})

export const sendTemplateSchema = z.object({
  conversationId,
  // The set is closed: only registry keys get past this point, never a client-supplied Meta name.
  templateKey: z.enum(TEMPLATE_KEYS, { errorMap: () => ({ message: 'Plantilla inválida' }) }),
  params: z
    .array(z.string({ invalid_type_error: 'Datos de plantilla inválidos' }), {
      required_error: 'Los datos de la plantilla son requeridos',
      invalid_type_error: 'Datos de plantilla inválidos',
    })
    .max(5, 'Datos de plantilla inválidos'),
})

export const resendFailedMessageSchema = z.object({
  messageId: z.string({ required_error: 'El mensaje es requerido' }).cuid('Mensaje inválido'),
  /** Required to resend a message whose delivery is unconfirmed: it may already have reached the customer. */
  confirmUnknownDelivery: z.boolean({ invalid_type_error: 'Confirmación inválida' }).default(false),
})

/** Text fields of the attachment upload (the file itself is validated from its bytes). */
export const sendMediaFieldsSchema = z.object({
  conversationId,
  caption: z
    .string({ invalid_type_error: 'Texto inválido' })
    .trim()
    .max(CAPTION_MAX_LENGTH, `El texto no puede superar ${CAPTION_MAX_LENGTH} caracteres`)
    .optional(),
})

// ---------------------------------------------------------------- handoff (PR2.4)

export const conversationActionSchema = z.object({ conversationId })

export const closeConversationSchema = z.object({
  conversationId,
  reason: z
    .string({ invalid_type_error: 'Motivo inválido' })
    .trim()
    .max(CLOSE_REASON_MAX_LENGTH, `El motivo no puede superar ${CLOSE_REASON_MAX_LENGTH} caracteres`)
    .optional(),
})

export const reopenConversationSchema = z.object({
  conversationId,
  target: z.enum(['AI', 'HUMAN'], {
    required_error: 'Indique quién atiende la conversación',
    invalid_type_error: 'Destino inválido',
  }),
})

export const setConversationAiPausedSchema = z.object({
  conversationId,
  paused: z.boolean({ required_error: 'Valor requerido', invalid_type_error: 'Valor inválido' }),
})

export const linkContactToClientSchema = z.object({
  conversationId,
  clientId: z.string({ required_error: 'El cliente es requerido' }).cuid('Cliente inválido'),
})

export const searchClientsForLinkSchema = z.object({
  q: z.string({ invalid_type_error: 'Búsqueda inválida' }).max(SEARCH_MAX_LENGTH, 'Búsqueda demasiado larga'),
})

export const getClientConversationsSchema = z.object({
  clientId: z.string({ required_error: 'El cliente es requerido' }).cuid('Cliente inválido'),
})

export const setAiEnabledSchema = z.object({
  enabled: z.boolean({ required_error: 'Valor requerido', invalid_type_error: 'Valor inválido' }),
})

export const USAGE_SUMMARY_MAX_DAYS = 90

export const getUsageSummarySchema = z.object({
  days: z
    .number({ invalid_type_error: 'Rango inválido' })
    .int('Rango inválido')
    .min(1, 'Rango inválido')
    .max(USAGE_SUMMARY_MAX_DAYS, 'Rango inválido')
    .default(30),
})

export const FORBIDDEN_TOPICS_MAX = 50
export const FORBIDDEN_TOPIC_MAX_LENGTH = 80

const optionalLimit = (max: number, label: string) =>
  z
    .number({ invalid_type_error: `${label} inválido` })
    .int(`${label} debe ser un número entero`)
    .min(1, `${label} debe ser al menos 1`)
    .max(max, `${label} no puede ser mayor a ${max}`)
    .nullable()

/** AI cost and abuse limits (Configuración → WhatsApp). null = use the server value, or no cap. */
export const updateAiLimitSettingsSchema = z.object({
  dailyBudgetUsd: z
    .number({ invalid_type_error: 'Tope diario inválido' })
    .positive('El tope diario debe ser mayor a 0')
    .max(100_000, 'El tope diario no puede ser mayor a 100000')
    .refine((value) => Number.isInteger(Math.round(value * 100 * 1e6) / 1e6), 'El tope diario admite máximo 2 decimales')
    .nullable(),
  maxTurnsPerDay: optionalLimit(1000, 'El límite de respuestas por día'),
  maxConsecutiveFailures: optionalLimit(10, 'El límite de fallas seguidas'),
  forbiddenTopics: z
    .array(z.string().max(FORBIDDEN_TOPIC_MAX_LENGTH, `Cada tema admite máximo ${FORBIDDEN_TOPIC_MAX_LENGTH} caracteres`))
    .max(FORBIDDEN_TOPICS_MAX, `Máximo ${FORBIDDEN_TOPICS_MAX} temas prohibidos`),
})

export type UpdateAiLimitSettingsInput = z.input<typeof updateAiLimitSettingsSchema>
export type SetAiEnabledInput = z.input<typeof setAiEnabledSchema>
export type GetUsageSummaryInput = z.input<typeof getUsageSummarySchema>
export type GetClientConversationsInput = z.input<typeof getClientConversationsSchema>
export type SearchClientsForLinkInput = z.input<typeof searchClientsForLinkSchema>
export type ConversationActionInput = z.input<typeof conversationActionSchema>
export type CloseConversationInput = z.input<typeof closeConversationSchema>
export type ReopenConversationInput = z.input<typeof reopenConversationSchema>
export type SetConversationAiPausedInput = z.input<typeof setConversationAiPausedSchema>
export type LinkContactToClientInput = z.input<typeof linkContactToClientSchema>

export type SendReplyInput = z.input<typeof sendReplySchema>
export type SendTemplateInput = z.input<typeof sendTemplateSchema>
export type ResendFailedMessageInput = z.input<typeof resendFailedMessageSchema>
export type ThreadCursor = z.infer<typeof threadCursor>
export type GetConversationThreadInput = z.input<typeof getConversationThreadSchema>
export type GetUpdatesInput = z.input<typeof getUpdatesSchema>
